function normalizeCit(str) {
  return String(str || "")
    .toLowerCase()
    .replace(/§§/g, " ss. ")
    .replace(/§/g, " s. ")
    .replace(/\b(?:sections|secs\.?|ss\.)\s*(?=[0-9(])/g, "ss. ")
    .replace(/\b(?:section|sec\.?|s\.)\s*(?=[0-9(])/g, "s. ")
    .replace(/\b(?:articles|arts\.?)\s*(?=[0-9(])/g, "arts. ")
    .replace(/\b(?:article|art\.?)\s*(?=[0-9(])/g, "art. ")
    .replace(/[^a-z0-9()\s]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function sendJson(res, status, payload) {
  const body = JSON.stringify(payload);
  res.writeHead(status, {
    "Content-Type": "application/json; charset=utf-8",
    "Content-Length": Buffer.byteLength(body),
  });
  res.end(body);
}

function readJsonBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let total = 0;
    req.on("data", (chunk) => {
      total += chunk.length;
      if (total > 1_500_000) {
        reject(Object.assign(new Error("Payload exceeds 1.5 MB"), { statusCode: 413 }));
        return;
      }
      chunks.push(chunk);
    });
    req.on("end", () => {
      try {
        const raw = Buffer.concat(chunks).toString("utf8");
        resolve(raw ? JSON.parse(raw) : {});
      } catch (err) {
        reject(Object.assign(new Error("Invalid JSON body"), { statusCode: 400 }));
      }
    });
    req.on("error", reject);
  });
}

